package com.meddibuddy.appointment;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="appointments",indexes=@Index(name="idx_appointment_doctor_date_time",columnList="doctorId,appointmentDate,appointmentTime",unique=true))
public class Appointment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String patientEmail; @Column(nullable=false) private Long doctorId; @Column(nullable=false) private String doctorName; @Column(nullable=false) private String specialty; @Column(nullable=false) private LocalDate appointmentDate; @Column(nullable=false) private String appointmentTime; @Column(nullable=false) private int fee; @Column(nullable=false) private String status="CONFIRMED"; private String reason; @Column(nullable=false) private Instant createdAt=Instant.now(); public Long getId(){return id;} public String getPatientEmail(){return patientEmail;} public void setPatientEmail(String v){patientEmail=v;} public Long getDoctorId(){return doctorId;} public void setDoctorId(Long v){doctorId=v;} public String getDoctorName(){return doctorName;} public void setDoctorName(String v){doctorName=v;} public String getSpecialty(){return specialty;} public void setSpecialty(String v){specialty=v;} public LocalDate getAppointmentDate(){return appointmentDate;} public void setAppointmentDate(LocalDate v){appointmentDate=v;} public String getAppointmentTime(){return appointmentTime;} public void setAppointmentTime(String v){appointmentTime=v;} public int getFee(){return fee;} public void setFee(int v){fee=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public Instant getCreatedAt(){return createdAt;} }
